public class Preview { public static void main(String[] a) throws Exception { if(a.length>1 && a[1].startsWith("flex")) com.hideo.foldplay.FlexRun.run(a[0], a[1].equals("flexland")); else if(a.length>1 && a[1].equals("emblems")) com.hideo.foldplay.EmblemsRun.run(a[0]); else if(a.length>1 && a[1].equals("icons")) com.hideo.foldplay.IconsRun.run(a[0]); else if(a.length>1 && a[1].equals("ambre")) com.hideo.foldplay.AmbreRun.run(a[0]); else if(a.length>1 && a[1].equals("red")) com.hideo.foldplay.RedRun.run(a[0]); else if(a.length>1) com.hideo.foldplay.CodecRun.run(a[0]); else com.hideo.foldplay.PreviewRun.run(a[0]); } }
